function toOrderDetail(serialno) {
    if (serialno != null && serialno != "") {
        redirectUrl("/WeixinService/business/query/orderDetailNew.shtml?serialno=" + serialno)
    } else {
        return;
    }
}

function tofundDetail(fundid,period,tradeacco){
	redirectUrl("/WeixinService/business/query/fundInfoNew.shtml?fundId=" + fundid+"&period="+period+"&tradeacco="+tradeacco)
}

function goToRedeem(fundId,period,serialNo){
	//redirectUrl("userRedeemNew.shtml?fundId="+fundId+"&period=1"+"&serialNo="+ serialNo);
	redirectUrl("userRedeemNew.shtml?fundId="+fundId+"&period="+period+"&serialNo="+ serialNo);
}


